config.script:
selectionData = self.parent.parent.getChild("TabContainer").getChild("Table_1").props.selection.data[0]
description = selectionData.Description

updateQuery = '''DECLARE @json nvarchar(max) = (SELECT config FROM QASawList WHERE active = 1);
				DECLARE @key  nvarchar(100) = ?;

				SET @json = JSON_MODIFY(
				    @json,
				    '$."' + STRING_ESCAPE(@key, 'json') + '"',
				    NULL
				);

				UPDATE QASawList
				SET config = @json
				WHERE active = 1;'''
updateArgs = [description]

system.db.runPrepUpdate(updateQuery, updateArgs, database = 'NLSTWDYK_DB_PROD')

self.props.value = 0
system.perspective.sendMessage('refreshSawList')

transforms.code:
rows = []

config = system.util.jsonDecode(value.getValueAt(0, 'Config'))
for tubeGroup in sorted(config):
	configDataRow = config[tubeGroup]['data']
	rowData = {'Description': tubeGroup, 'Version': value.getValueAt(0, 'VersionID'), 'SawListID': value.getValueAt(0, 'SawListID')}

	for configData in configDataRow:
		testData = configDataRow[configData]

		for configSetting in testData.keys():
			rowData[configData + configSetting] = configDataRow[configData][configSetting]
	rows.append(rowData)
return rows
